const recent=new WeakMap();
// Short cached-context noise bursts; no network audio and no persistent sound loop.
export function playTableSound(ctx,kind){const presets={deal:[.11,1700,.045,'highpass'],chips:[.09,2700,.065,'bandpass'],dice:[.075,850,.10,'lowpass'],ball:[.045,2100,.045,'bandpass'],roll:[.22,1300,.045,'bandpass']},p=presets[kind];if(!p)return false;let last=recent.get(ctx);if(!last)recent.set(ctx,last=new Map());const t=ctx.currentTime;if(t-(last.get(kind)??-1)<.055)return true;last.set(kind,t);const [length,hz,volume,type]=p,buffer=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*length),ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();source.buffer=buffer;filter.type=type;filter.frequency.value=hz;filter.Q.value=kind==='chips'?4:1;source.connect(filter);filter.connect(gain);gain.connect(ctx.destination);gain.gain.setValueAtTime(volume,t);gain.gain.exponentialRampToValueAtTime(.001,t+length);source.onended=()=>{source.disconnect();filter.disconnect();gain.disconnect()};source.start(t);source.stop(t+length);return true}
export function tweenSound(tw,time){if(tw.sounded||time<tw.start)return null;const chip=tw.obj.userData.sound==='chips',at=tw.start+(chip?tw.duration*.75:0);if(time<at)return null;tw.sounded=true;if(time-at>.25)return null;return chip?'chips':tw.obj.userData.face?'deal':null}
export function rouletteSoundEvents(g,previous,now){if(previous===undefined||now-previous>300||g.launchAt===null)return[];const out=[];if(previous<g.launchAt&&now>=g.launchAt)out.push('roll');if(previous<g.launchAt+650&&now>=g.launchAt+650)out.push('ball');if(now>=g.closeAt&&now<g.landAt){const step=t=>Math.floor(Math.max(0,t-g.closeAt)/(g.landAt-g.closeAt)*45/Math.PI);if(step(now)>step(previous))out.push('ball')}if(previous<g.landAt&&now>=g.landAt)out.push('ball');return out}
